import { createHash, randomBytes } from "node:crypto";
import type {
  Clock,
  MembershipRepository,
  PasswordVerifier,
  SessionRepository,
  SessionTokenService,
  UserIdentityRepository,
} from "../../../src/modules/identity/ports/index.js";
import type {
  UserIdentity,
  UserMembership,
  UserSession,
} from "../../../src/modules/identity/identity.types.js";

export class FakeUserIdentityRepository implements UserIdentityRepository {
  private users = new Map<string, UserIdentity>();

  add(user: UserIdentity): void {
    this.users.set(user.id, user);
    this.users.set(user.loginIdentifier, user);
  }

  async findByIdentifier(identifier: string): Promise<UserIdentity | null> {
    return this.users.get(identifier) ?? null;
  }

  async findById(userId: string): Promise<UserIdentity | null> {
    return this.users.get(userId) ?? null;
  }
}

export class FakeMembershipRepository implements MembershipRepository {
  private memberships: UserMembership[] = [];

  add(...memberships: UserMembership[]): void {
    this.memberships.push(...memberships);
  }

  async findActiveMembershipsByUser(
    userId: string,
  ): Promise<readonly UserMembership[]> {
    return this.memberships.filter((m) => m.userId === userId);
  }

  async findByUserAndSchool(
    userId: string,
    schoolId: string,
  ): Promise<UserMembership | null> {
    return (
      this.memberships.find(
        (m) => m.userId === userId && m.schoolId === schoolId,
      ) ?? null
    );
  }
}

export class FakePasswordVerifier implements PasswordVerifier {
  private passwords = new Map<string, string>();
  readonly calls: Array<{ kind: "real" | "dummy"; password: string }> = [];

  register(userId: string, password: string): void {
    this.passwords.set(userId, password);
  }

  async verify(password: string, hash: string): Promise<boolean> {
    this.calls.push({ kind: "real", password });
    // In tests, the "hash" is the userId placeholder recorded by fixtures.
    const expected = this.passwords.get(hash);
    return expected === password;
  }

  async verifyDummy(password: string): Promise<boolean> {
    this.calls.push({ kind: "dummy", password });
    return false;
  }
}

export class FakeSessionTokenService implements SessionTokenService {
  private counter = 0;

  async generatePair(): Promise<{
    accessToken: string;
    refreshToken: string;
  }> {
    this.counter += 1;
    const accessToken = `access-token-${this.counter}-${randomBytes(8).toString("hex")}`;
    const refreshToken = `refresh-token-${this.counter}-${randomBytes(8).toString("hex")}`;
    return { accessToken, refreshToken };
  }

  async hash(token: string): Promise<string> {
    return createHash("sha256").update(token).digest("hex");
  }
}

export class FakeSessionRepository implements SessionRepository {
  private sessionsById = new Map<string, UserSession>();
  private accessIndex = new Map<string, string>();
  private refreshIndex = new Map<string, string>();
  private nextId = 1;
  private failNextRotation = false;

  async create(
    params: Readonly<{
      userId: string;
      activeSchoolId: string | null;
      accessTokenHash: string;
      refreshTokenHash: string;
      accessExpiresAt: Date;
      refreshExpiresAt: Date;
    }>,
  ): Promise<UserSession> {
    const session: UserSession = {
      id: `session-${this.nextId++}`,
      ...params,
      revokedAt: null,
      createdAt: new Date(),
      lastUsedAt: new Date(),
    };
    this.store(session);
    return session;
  }

  async findByAccessTokenHash(
    accessTokenHash: string,
  ): Promise<UserSession | null> {
    const id = this.accessIndex.get(accessTokenHash);
    return id ? (this.sessionsById.get(id) ?? null) : null;
  }

  async findByRefreshTokenHash(
    refreshTokenHash: string,
  ): Promise<UserSession | null> {
    const id = this.refreshIndex.get(refreshTokenHash);
    return id ? (this.sessionsById.get(id) ?? null) : null;
  }

  async revoke(sessionId: string): Promise<void> {
    const session = this.sessionsById.get(sessionId);
    if (session) {
      session.revokedAt = new Date();
    }
  }

  async compareAndRotateRefreshSession(
    params: Readonly<{
      sessionId: string;
      expectedRefreshTokenHash: string;
      now: Date;
      successor: {
        activeSchoolId: string | null;
        accessTokenHash: string;
        refreshTokenHash: string;
        accessExpiresAt: Date;
        refreshExpiresAt: Date;
      };
    }>,
  ): Promise<UserSession | null> {
    const session = this.sessionsById.get(params.sessionId);
    if (
      this.failNextRotation ||
      !session ||
      session.revokedAt ||
      session.refreshTokenHash !== params.expectedRefreshTokenHash ||
      session.refreshExpiresAt <= params.now
    ) {
      this.failNextRotation = false;
      return null;
    }
    session.revokedAt = params.now;
    const successor: UserSession = {
      id: `session-${this.nextId++}`,
      userId: session.userId,
      ...params.successor,
      revokedAt: null,
      createdAt: params.now,
      lastUsedAt: params.now,
    };
    this.store(successor);
    return successor;
  }

  sessionCount(): number {
    return this.sessionsById.size;
  }

  activeSessionCount(): number {
    return [...this.sessionsById.values()].filter(
      (session) => !session.revokedAt,
    ).length;
  }

  failNextCompareAndRotate(): void {
    this.failNextRotation = true;
  }

  private store(session: UserSession): void {
    this.sessionsById.set(session.id, session);
    this.accessIndex.set(session.accessTokenHash, session.id);
    this.refreshIndex.set(session.refreshTokenHash, session.id);
  }
}

export class FakeClock implements Clock {
  constructor(private time = new Date()) {}

  now(): Date {
    return new Date(this.time.getTime());
  }

  advance(ms: number): void {
    this.time = new Date(this.time.getTime() + ms);
  }
}

import type {
  CommunityRepositoryPort,
  CreatePostData,
  UpdatePostData,
  UpdatePostStatusData,
  CreateCommentData,
  CreateReportData,
  UpdateReportStatusData,
  ListPostsOptions,
  ListCommentsOptions,
  ListReportsOptions,
  PaginatedResult,
} from "../../../../src/modules/community/ports/community-repository.port.js";
import type {
  CommunityPost,
  PostComment,
  ContentReport,
} from "../../../../src/modules/community/domain/community.types.js";

/**
 * In-memory fake implementation of CommunityRepositoryPort for testing.
 *
 * All data is stored in simple arrays and maps so that tests can
 * inspect state and set up preconditions without a real database.
 */
export class FakeCommunityRepository implements CommunityRepositoryPort {
  private readonly posts = new Map<string, CommunityPost>();
  private readonly comments = new Map<string, PostComment>();
  private readonly reports = new Map<string, ContentReport>();
  private nextId = 1;

  /* ---------- helpers for test setup ---------- */

  /** Seed a post into the store. */
  addPost(post: CommunityPost): this {
    this.posts.set(post.id, post);
    return this;
  }

  /** Seed a report into the store. */
  addReport(report: ContentReport): this {
    this.reports.set(report.id, report);
    return this;
  }

  /** Seed a comment into the store. */
  addComment(comment: PostComment): this {
    this.comments.set(comment.id, comment);
    return this;
  }

  /** Get a stored post by id (useful for assertions). */
  getPost(id: string): CommunityPost | undefined {
    return this.posts.get(id);
  }

  /** Get a stored report by id. */
  getReport(id: string): ContentReport | undefined {
    return this.reports.get(id);
  }

  /* ---------- CommunityRepositoryPort ---------- */

  async findPostById(
    _schoolId: string,
    postId: string,
  ): Promise<CommunityPost | null> {
    return this.posts.get(postId) ?? null;
  }

  async listPosts(
    schoolId: string,
    options: ListPostsOptions,
  ): Promise<PaginatedResult<CommunityPost>> {
    let items = [...this.posts.values()].filter(
      (p) => p.schoolId === schoolId,
    );

    if (options.status !== undefined) {
      items = items.filter((p) => p.status === options.status);
    }
    if (options.contentType !== undefined) {
      items = items.filter((p) => p.contentType === options.contentType);
    }
    if (options.authorUserId !== undefined) {
      items = items.filter((p) => p.authorUserId === options.authorUserId);
    }

    // Simple cursor-based pagination using offset stored in cursor string
    const cursor = options.cursor !== undefined ? Number(options.cursor) : 0;
    const sliced = items.slice(cursor, cursor + options.limit);
    const nextOffset = cursor + options.limit;
    const hasMore = nextOffset < items.length;

    return {
      items: sliced,
      nextCursor: hasMore ? String(nextOffset) : null,
      hasMore,
    };
  }

  async createPost(data: CreatePostData): Promise<CommunityPost> {
    const now = new Date();
    const id = `post-${this.nextId++}`;
    const post: CommunityPost = {
      id,
      schoolId: data.schoolId,
      authorUserId: data.authorUserId,
      title: data.title,
      contentType: data.contentType,
      content: data.content,
      attachmentObjectKey: data.attachmentObjectKey,
      status: "DRAFT" as CommunityPost["status"],
      visibilityScope: data.visibilityScope,
      createdAt: now,
      updatedAt: now,
      revision: 1,
    };
    this.posts.set(id, post);
    return post;
  }

  async updatePost(
    _schoolId: string,
    postId: string,
    data: UpdatePostData,
  ): Promise<CommunityPost> {
    const existing = this.posts.get(postId);
    if (!existing) {
      throw new Error(`Post ${postId} not found`);
    }
    const updated: CommunityPost = {
      ...existing,
      ...(data.title !== undefined ? { title: data.title } : {}),
      ...(data.content !== undefined ? { content: data.content } : {}),
      updatedAt: new Date(),
      revision: existing.revision + 1,
    };
    this.posts.set(postId, updated);
    return updated;
  }

  async updatePostStatus(
    _schoolId: string,
    postId: string,
    data: UpdatePostStatusData,
  ): Promise<CommunityPost> {
    const existing = this.posts.get(postId);
    if (!existing) {
      throw new Error(`Post ${postId} not found`);
    }
    const updated: CommunityPost = {
      ...existing,
      status: data.status,
      reviewedBy: data.reviewedBy ?? existing.reviewedBy,
      reviewNote: data.reviewNote ?? existing.reviewNote,
      publishedAt: data.publishedAt ?? existing.publishedAt,
      updatedAt: new Date(),
      revision: existing.revision + 1,
    };
    this.posts.set(postId, updated);
    return updated;
  }

  async listComments(
    _schoolId: string,
    postId: string,
    options: ListCommentsOptions,
  ): Promise<PaginatedResult<PostComment>> {
    let items = [...this.comments.values()].filter(
      (c) => c.postId === postId,
    );

    const cursor = options.cursor !== undefined ? Number(options.cursor) : 0;
    const sliced = items.slice(cursor, cursor + options.limit);
    const nextOffset = cursor + options.limit;
    const hasMore = nextOffset < items.length;

    return {
      items: sliced,
      nextCursor: hasMore ? String(nextOffset) : null,
      hasMore,
    };
  }

  async createComment(data: CreateCommentData): Promise<PostComment> {
    const now = new Date();
    const id = `comment-${this.nextId++}`;
    const comment: PostComment = {
      id,
      postId: data.postId,
      authorUserId: data.authorUserId,
      content: data.content,
      createdAt: now,
      updatedAt: now,
    };
    this.comments.set(id, comment);
    return comment;
  }

  async createReport(data: CreateReportData): Promise<ContentReport> {
    const now = new Date();
    const id = `report-${this.nextId++}`;
    const report: ContentReport = {
      id,
      schoolId: data.schoolId,
      postId: data.postId,
      reporterUserId: data.reporterUserId,
      reason: data.reason,
      description: data.description,
      status: "PENDING" as ContentReport["status"],
      createdAt: now,
    };
    this.reports.set(id, report);
    return report;
  }

  async listReports(
    schoolId: string,
    options: ListReportsOptions,
  ): Promise<PaginatedResult<ContentReport>> {
    let items = [...this.reports.values()].filter(
      (r) => r.schoolId === schoolId,
    );

    if (options.status !== undefined) {
      items = items.filter((r) => r.status === options.status);
    }

    const cursor = options.cursor !== undefined ? Number(options.cursor) : 0;
    const sliced = items.slice(cursor, cursor + options.limit);
    const nextOffset = cursor + options.limit;
    const hasMore = nextOffset < items.length;

    return {
      items: sliced,
      nextCursor: hasMore ? String(nextOffset) : null,
      hasMore,
    };
  }

  async updateReportStatus(
    _schoolId: string,
    reportId: string,
    data: UpdateReportStatusData,
  ): Promise<ContentReport> {
    const existing = this.reports.get(reportId);
    if (!existing) {
      throw new Error(`Report ${reportId} not found`);
    }
    const updated: ContentReport = {
      ...existing,
      status: data.status,
      reviewedBy: data.reviewedBy,
      reviewedAt: data.reviewedAt,
    };
    this.reports.set(reportId, updated);
    return updated;
  }

  async findReportById(
    _schoolId: string,
    reportId: string,
  ): Promise<ContentReport | null> {
    return this.reports.get(reportId) ?? null;
  }
}

import type {
  CooperationLead,
  SupportApplication,
  VolunteerApplication,
  LeadStatus,
  ApplicationStatus,
  VolunteerAppStatus,
} from "../../../../src/modules/cooperation/domain/cooperation.types.js";
import type {
  CooperationRepositoryPort,
  ListLeadsOptions,
  ListSupportApplicationsOptions,
  ListVolunteerApplicationsOptions,
  PaginatedResult,
} from "../../../../src/modules/cooperation/ports/cooperation-repository.port.js";

export class FakeCooperationRepository implements CooperationRepositoryPort {
  private leads: Map<string, CooperationLead> = new Map();
  private supportApplications: Map<string, SupportApplication> = new Map();
  private volunteerApplications: Map<string, VolunteerApplication> = new Map();
  private nextLeadId = 1;
  private nextAppId = 1;
  private nextVolAppId = 1;

  // ---------- Leads ----------

  async createLead(
    data: Omit<CooperationLead, "id" | "status" | "createdAt" | "updatedAt">,
  ): Promise<CooperationLead> {
    const now = new Date();
    const lead: CooperationLead = {
      id: `lead-${this.nextLeadId++}`,
      ...data,
      status: "NEW" as LeadStatus,
      createdAt: now,
      updatedAt: now,
    };
    this.leads.set(lead.id, lead);
    return lead;
  }

  async findLeadById(leadId: string): Promise<CooperationLead | null> {
    return this.leads.get(leadId) ?? null;
  }

  async listLeads(options: ListLeadsOptions): Promise<PaginatedResult<CooperationLead>> {
    let items = [...this.leads.values()];

    if (options.status) {
      items = items.filter((l) => l.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor
      ? items.findIndex((i) => i.id === options.cursor) + 1
      : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor: hasMore && slice.length > 0 ? slice[slice.length - 1].id : null,
      hasMore,
    };
  }

  async updateLeadStatus(
    leadId: string,
    status: LeadStatus,
    assignedOperatorId?: string,
  ): Promise<CooperationLead> {
    const existing = this.leads.get(leadId);
    if (!existing) throw new Error(`Lead ${leadId} not found`);
    const updated: CooperationLead = {
      ...existing,
      status,
      ...(assignedOperatorId !== undefined ? { assignedOperatorId } : {}),
      updatedAt: new Date(),
    };
    this.leads.set(leadId, updated);
    return updated;
  }

  // ---------- Support Applications ----------

  async createSupportApplication(
    data: Omit<SupportApplication, "id" | "status" | "createdAt" | "updatedAt">,
  ): Promise<SupportApplication> {
    const now = new Date();
    const application: SupportApplication = {
      id: `app-${this.nextAppId++}`,
      ...data,
      status: "PENDING" as ApplicationStatus,
      createdAt: now,
      updatedAt: now,
    };
    this.supportApplications.set(application.id, application);
    return application;
  }

  async findSupportApplicationById(
    applicationId: string,
  ): Promise<SupportApplication | null> {
    return this.supportApplications.get(applicationId) ?? null;
  }

  async listSupportApplications(
    options: ListSupportApplicationsOptions,
  ): Promise<PaginatedResult<SupportApplication>> {
    let items = [...this.supportApplications.values()];

    if (options.status) {
      items = items.filter((a) => a.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor
      ? items.findIndex((i) => i.id === options.cursor) + 1
      : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor: hasMore && slice.length > 0 ? slice[slice.length - 1].id : null,
      hasMore,
    };
  }

  async updateSupportApplicationStatus(
    applicationId: string,
    status: ApplicationStatus,
    reviewedBy?: string,
    reviewNote?: string,
  ): Promise<SupportApplication> {
    const existing = this.supportApplications.get(applicationId);
    if (!existing) throw new Error(`Application ${applicationId} not found`);
    const updated: SupportApplication = {
      ...existing,
      status,
      reviewedBy,
      reviewedAt: new Date(),
      reviewNote,
      updatedAt: new Date(),
    };
    this.supportApplications.set(applicationId, updated);
    return updated;
  }

  // ---------- Volunteer Applications ----------

  async createVolunteerApplication(
    data: Omit<VolunteerApplication, "id" | "status" | "createdAt" | "updatedAt">,
  ): Promise<VolunteerApplication> {
    const now = new Date();
    const application: VolunteerApplication = {
      id: `volapp-${this.nextVolAppId++}`,
      ...data,
      status: "PENDING" as VolunteerAppStatus,
      createdAt: now,
      updatedAt: now,
    };
    this.volunteerApplications.set(application.id, application);
    return application;
  }

  async findVolunteerApplicationById(
    applicationId: string,
  ): Promise<VolunteerApplication | null> {
    return this.volunteerApplications.get(applicationId) ?? null;
  }

  async listVolunteerApplications(
    options: ListVolunteerApplicationsOptions,
  ): Promise<PaginatedResult<VolunteerApplication>> {
    let items = [...this.volunteerApplications.values()];

    if (options.status) {
      items = items.filter((a) => a.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor
      ? items.findIndex((i) => i.id === options.cursor) + 1
      : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor: hasMore && slice.length > 0 ? slice[slice.length - 1].id : null,
      hasMore,
    };
  }

  async updateVolunteerApplicationStatus(
    applicationId: string,
    status: VolunteerAppStatus,
